33	    private int _frame;
34	
35	    public Game1(string[]? args = null)
36	    {
37	        _headless = HeadlessOptions.Parse(args);
38	        // The editor run configuration: `--editor` launch arg or MONODREAMS_EDITOR=1 env var.
39	        // When active, every demo screen composes the editor overlay and the host boots straight
40	        // the transport Paused (RunMode.Edit). Honoured under --headless too: headless Demos renders
41	        // every frame (the observe-and-self-verify channel), so an editor-flagged headless run
42	        // captures the shell in its PNGs — the editor's own self-verification path. The flag-off
43	        // headless contract (HeadlessDemoTests) is untouched.
44	        _editor = EditorRunFlag.IsEnabled(args, Environment.GetEnvironmentVariable);
45	
46	        _graphics = new GraphicsDeviceManager(this);
47	        Content.RootDirectory = "Content";
48	        IsMouseVisible = false;
49	        // Platform-conditional: desktop GL supports HiDef; a web (BlazorGL/WebGL)
50	        // head defines MONODREAMS_WEB and falls back to Reach. Selected by the head.
51	#if MONODREAMS_WEB
52	        _graphics.GraphicsProfile = GraphicsProfile.Reach;
53	#else
54	        _graphics.GraphicsProfile = GraphicsProfile.HiDef;
55	#endif
56	        // Headless still renders at full virtual resolution into a real backbuffer —
57	        // the window is just hidden off-screen and never relied on for presentation.
58	        // The render path (and its memory behaviour) is exercised exactly as in a
59	        // visible run, which is the whole point: a 1×1 window would make the captured
60	        // frame meaningless. See issue #28 and the debug-module premises.
61	        _graphics.PreferredBackBufferWidth = VirtualWidth;
62	        _graphics.PreferredBackBufferHeight = VirtualHeight;
63	        if (_headless.Enabled)
64	        {
65	            _graphics.SynchronizeWithVerticalRetrace = false;
66	            IsFixedTimeStep = false;
67	        }
68	        else
69	        {
70	            _graphics.SynchronizeWithVerticalRetrace = true;
71	            IsFixedTimeStep = true;
72	        }
73	        _graphics.ApplyChanges();
74	
75	        _viewportManager = new ViewportManager(this, VirtualWidth, VirtualHeight);
76	        _camera = new Camera(VirtualWidth, VirtualHeight);
77	
78	        // OS-window resize is a desktop concern; a web head sizes from the host page.
79	#if !MONODREAMS_WEB
