92	    private void InitializeRenderer(int realScreenWidth, int realScreenHeight)
93	    {
94	        _viewportManager.ScreenWidth = realScreenWidth;
95	        _viewportManager.ScreenHeight = realScreenHeight;
96	        _camera.RecalculateTransformationMatrices();
97	    }
