99	    protected override void Initialize()
100	    {
101	        var debugDir = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
102	            ?? PlatformServices.Current.CombinePath(PlatformServices.Current.BaseDirectory, "debug");
103	        Logger.Initialize(debugDir);
