1	using System;
2	using System.Collections.Generic;
3	using System.Diagnostics;
4	using System.Linq;
5	using System.Text.RegularExpressions;
6	using DefaultEcs.System;
7	using Microsoft.Xna.Framework;
8	using MonoDreams.Debug;
9	using MonoDreams.LevelEditor.Composition;
10	using MonoDreams.State;
11	using MonoDreams.System;
12	using Xunit;
13	
14	// Folder/namespace note: this lives under `Profiling/`, not `Debug/`, because
15	// `.gitignore` ignores `/MonoDreams.Tests/[Dd]ebug/` as a build-output directory — a test file
16	// there would compile locally and never be committed.
17	namespace MonoDreams.Tests.Profiling;
18	
19	/// <summary>
20	/// Protects the optional per-system frame-time profiler: it plugs itself into foundation's
21	/// <see cref="GatedSystem.TimingSink"/> socket (foundation never references it back — see
22	/// <c>GatedSystemTimingSinkTests.Foundation_SourcesNeverReferenceDebugModule</c>), accumulates a
23	/// window of ticks per profile name, and renders it as a table whose shape is a <b>grep contract</b>
24	/// (the report is read out of a log file, on desktop and in a browser console alike).
25	///
26	/// <para>Every gate a screen registers through <see cref="EditorPipelineRegistrar"/> carries the
27	/// entry's full hierarchical name, so the report's rows ARE the pipeline tree — that end-to-end path
28	/// is asserted here rather than only at the naming seam.</para>
29	///
30	/// <para><b>Static state.</b> <see cref="SystemProfiler"/>'s window and the timing socket are
31	/// process-wide, so this class shares the <c>SystemProfilerStatics</c> collection with
32	/// <c>GatedSystemTimingSinkTests</c> and fully resets both in its constructor and
33	/// <see cref="Dispose"/>. Profile names are test-local and assertions on the report are
34	/// containment-based, so a stray recording could never make a test here flake.</para>
35	/// </summary>
36	[Collection("SystemProfilerStatics")]
37	public class SystemProfilerTests : IDisposable
38	{
39	    /// <summary>The header's fixed shape: <c>[perf] {frames} frames, {ms}ms/frame in profiled
40	    /// systems:</c>. The decimal separator is matched as <c>[.,]</c> so the contract test is about
41	    /// the LAYOUT and not about the machine's locale.</summary>
42	    private static readonly Regex HeaderContract =
43	        new(@"^\[perf\] \d+ frames, \d+[.,]\d\dms/frame in profiled systems:$", RegexOptions.Compiled);
44	
45	    /// <summary>A row's fixed shape: indented name, then ms/frame to three decimals suffixed
46	    /// <c>ms</c>, then the share to one decimal suffixed <c>%</c>. Anchored on those two suffixes so
47	    /// the fixed-width padding may change without breaking the test.</summary>
48	    private static readonly Regex RowContract =
49	        new(@"^\s+\S.*\s\d+[.,]\d{3}ms\s+\d+[.,]\d%$", RegexOptions.Compiled);
50	
51	    /// <summary>The name the drain uses to force a report (and therefore a window reset); never
52	    /// asserted on, and gone by the time any test body runs.</summary>
53	    private const string DrainMarker = "__drain__";
54	
55	    /// <summary>
56	    /// A child system that burns a measurable slice of wall clock, so the recorded tick span (and
57	    /// therefore the report's ms/frame and share columns) is never zero — a zero total would make
58	    /// the share column degenerate and the format assertions meaningless.
59	    /// </summary>
60	    private sealed class BusySystem : ISystem<GameState>
61	    {
62	        private readonly long _ticks;
63	        public int UpdateCount { get; private set; }
64	        public bool IsEnabled { get; set; } = true;
65	
66	        public BusySystem(double milliseconds = 0.2)
67	            => _ticks = Math.Max(1L, (long)(Stopwatch.Frequency * milliseconds / 1000.0));
68	
69	        public void Update(GameState state)
70	        {
71	            if (!IsEnabled) return;
72	            UpdateCount++;
73	            var start = Stopwatch.GetTimestamp();
74	            while (Stopwatch.GetTimestamp() - start < _ticks) { }
75	        }
76	
77	        public void Dispose() { }
78	    }
79	
80	    private static GameState NewState(RunMode mode) => new(new GameTime()) { RunMode = mode };
81	
82	    private static GatedSystem NamedGate(string profileName, ISystem<GameState> child,
83	        EditTimeBehavior policy = EditTimeBehavior.RunNormally)
84	        => new(child, policy) { ProfileName = profileName };
85	
86	    public SystemProfilerTests() => ResetStatics();
87	
88	    public void Dispose() => ResetStatics();
89	
90	    private static void ResetStatics()
91	    {
92	        SystemProfiler.Enabled = false;  // the setter also uninstalls the sink
